# Choose a nontrivial start and subset size; keep sizes moderate to avoid trivialities
start = rng.randint(3, 9)  # small positive start ensures delicate threshold behavior
subset_size = rng.randint(8, 12)  # ensure sufficiently large to be challenging
return {'start': start, 'subset_size': subset_size}

