    return (False, None)
# Difficulty guardrails: avoid trivial or degenerate settings
if start < 3:
    # very small start can cause edge cases; enforce start >= 3
    return (False, None)
if s < 7 or s > 60:
    # subset size too small or too large; keep within reasonable contest bounds
    return (False, None)
# Core computation: minimal acute-free extremal sequence
# Define r_1 = start, r_2 = start+1, and for k>=3, r_k = ceil(sqrt(r_{k-1}^2 + r_{k-2}^2)).
# The largest n such that every s-element subset has an acute triangle is r_s - 1.
r1 = start
r2 = start + 1
seq = [r1, r2]
for k in range(3, s+1):
    X = seq[-1]*seq[-1] + seq[-2]*seq[-2]
    r = math.isqrt(X)
    if r*r < X:
        r += 1
    seq.append(r)
ans = seq[-1] - 1
# Sanity and difficulty validation:
# Check that with n = ans + 1 we can indeed construct an acute-free subset of size s (greedy extremal sequence fits),
# and with n = ans we cannot.
N_plus = ans + 1
greedy = [start, start+1]
while len(greedy) < s:
    X = greedy[-1]*greedy[-1] + greedy[-2]*greedy[-2]
    r = math.isqrt(X)
    if r*r < X:
        r += 1
    if r > N_plus:
        # Should not happen: by construction N_plus >= r_s, so sequence must fit
        return (False, None)
    greedy.append(r)
# Now verify impossibility at N = ans
N = ans
greedy2 = [start, start+1]
possible = True
while len(greedy2) < s:
    X = greedy2[-1]*greedy2[-1] + greedy2[-2]*greedy2[-2]
    r = math.isqrt(X)
    if r*r < X:
        r += 1
    if r > N:
        possible = False
        break
    greedy2.append(r)
if possible:
    # If we could fit s elements at N = ans, then ans is not the largest such n.
    return (False, None)
# Additional mild hardness check: ensure the threshold is not trivially close to start
# (keeps instances from being solved by immediate observation)
if ans - start < s + 3:
    # Too small a gap could be trivial; reject such instances
    return (False, None)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

